contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint256 beforeBalance = address(c).balance;
        uint256 selfBefore = address(this).balance;
        address beforeOwner = c.Owner(); if (__ESBMC_reverted()) return;

        c.withdraw(); if (__ESBMC_reverted()) return;

        assert(
            c.Owner() == beforeOwner &&
            address(c).balance == 0 &&
            address(this).balance == selfBefore + beforeBalance
        );
    }
}

