pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeBalance = address(c).balance;
        uint256 selfBefore = address(this).balance;
        address beforeOwner;
        try c.Owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        try c.withdraw() {} catch { return; }
        assertTrue(c.Owner() == beforeOwner &&
            address(c).balance == 0 &&
            address(this).balance == selfBefore + beforeBalance);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
